@Component({
  selector: 'app-topic-card',
  imports: [DifficultyChipComponent, PriorityChipComponent],
  templateUrl: './topic-card.html',
})
export class TopicCardComponent {
  topic = input.required<TopicSummary>();
}

export class TopicTimerComponent implements OnInit, OnDestroy {
  private intervalId?: ReturnType<typeof setInterval>;

  ngOnInit(): void {
    this.intervalId = setInterval(() => this.tick(), 1000);
  }

  ngOnDestroy(): void {
    clearInterval(this.intervalId);
  }

  private tick(): void {}
}

@Injectable({ providedIn: 'root' })
export class ContentService {
  private readonly http = inject(HttpClient);
}

@Component({
  selector: 'app-progress-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<p>{{ percentage() }}%</p>`,
})
export class ProgressCardComponent {
  percentage = input.required<number>();
}

private readonly _progress = signal<Record<string, TopicProgress>>({});
readonly progress = this._progress.asReadonly();

readonly completedCount = computed(() =>
  Object.values(this._progress()).filter(p => p.status === 'completed').length
);

searchTerm$.pipe(
  debounceTime(250),
  distinctUntilChanged(),
  switchMap(term => this.contentService.search(term))
).subscribe(results => this.results.set(results));

export const loggingInterceptor: HttpInterceptorFn = (req, next) => {
  const started = Date.now();
  return next(req).pipe(
    tap(() => console.log(`${req.url} took ${Date.now() - started}ms`))
  );
};
